// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }

    // fuzzed params: an actor address and an amount to deposit then withdraw
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        // keep amount in a reasonable range to avoid overflow issues in the fuzzer
        amount = bound(amount, 0, 1 ether);
        vm.assume(actor != address(0));

        // fund the actor so they can send ETH to the contract
        vm.deal(actor, amount);

        // actor deposits by sending ETH to the contract via fallback
        vm.prank(actor);
        // if amount is zero this is a no-op but still admissible
        (bool sent,) = payable(address(c)).call{value: amount}("");
        require(sent);

        // record contract balance before withdraw
        uint256 before = address(c).balance;

        // actor calls withdraw; capture whether it reverted or not
        bool ok;
        vm.prank(actor);
        try c.withdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        // After a successful withdraw on the reference implementation, the contract's balance
        // must have decreased by the caller's prior recorded balance (which equals `amount`).
        // We express a universal property: if withdraw returned (ok == true) and the actor had
        // deposited `amount` (i.e., amount > 0), then address(c).balance < before.
        // The mutant that deletes the external call will still zero the recorded balance but will
        // NOT send ETH out, so for some inputs (amount > 0) this assertion will fail on the mutant.

        if (ok && amount > 0) {
            assertTrue(address(c).balance < before);
        } else {
            // if withdraw reverted or amount == 0, the property does not assert a decrease
            assertTrue(true);
        }
    }
}
